package com.sobrenaturaldirector.mutation.model;
public final class MutationBudget {private final long volumeUnits;private final int componentCount,complexityUnits,destructiveCount,maxIntents,maxEdges,maxVerifications;public MutationBudget(long volumeUnits,int componentCount,int complexityUnits,int destructiveCount,int maxIntents,int maxEdges,int maxVerifications){if(volumeUnits<=0||componentCount<=0||complexityUnits<=0||destructiveCount<0||maxIntents<=0||maxEdges<0||maxVerifications<=0)throw new IllegalArgumentException("invalid mutation budget");this.volumeUnits=volumeUnits;this.componentCount=componentCount;this.complexityUnits=complexityUnits;this.destructiveCount=destructiveCount;this.maxIntents=maxIntents;this.maxEdges=maxEdges;this.maxVerifications=maxVerifications;}public long getVolumeUnits(){return volumeUnits;}public int getComponentCount(){return componentCount;}public int getComplexityUnits(){return complexityUnits;}public int getDestructiveCount(){return destructiveCount;}public int getMaxIntents(){return maxIntents;}public int getMaxEdges(){return maxEdges;}public int getMaxVerifications(){return maxVerifications;}}
